export const EMBEDDED_SETUP_HTML = "<!DOCTYPE html>\n<html lang=\"hu\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Crucix Intelligence — Beállító Központ</title>\n  <link rel=\"icon\" href=\"data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'><text y='.9em' font-size='90'>🌐</text></svg>\">\n  <link rel=\"stylesheet\" href=\"vendor/fonts.css\">\n  <style>\n    :root {\n      --bg: #03080e;\n      --panel: rgba(5, 14, 24, 0.92);\n      --panel-border: rgba(100, 240, 200, 0.2);\n      --panel-border-focus: rgba(100, 240, 200, 0.6);\n      --accent: #64f0c8;\n      --accent2: #44ccff;\n      --danger: #ff5f63;\n      --warn: #ffb84c;\n      --text: #e8f4f0;\n      --dim: #8aa0a8;\n      --mono: 'IBM Plex Mono', monospace;\n      --sans: 'Space Grotesk', system-ui, sans-serif;\n    }\n\n    * { box-sizing: border-box; margin: 0; padding: 0; }\n\n    body {\n      background-color: var(--bg);\n      color: var(--text);\n      font-family: var(--sans);\n      min-height: 100vh;\n      display: flex;\n      flex-direction: column;\n      background-image: \n        radial-gradient(circle at 50% 0%, rgba(68, 204, 255, 0.08) 0%, transparent 60%),\n        linear-gradient(rgba(255, 255, 255, 0.02) 1px, transparent 1px),\n        linear-gradient(90deg, rgba(255, 255, 255, 0.02) 1px, transparent 1px);\n      background-size: 100% 100%, 32px 32px, 32px 32px;\n      padding: 24px 16px 80px;\n    }\n\n    .container {\n      max-width: 900px;\n      margin: 0 auto;\n      width: 100%;\n    }\n\n    /* TOP HEADER */\n    header {\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      border-bottom: 1px solid var(--panel-border);\n      padding-bottom: 20px;\n      margin-bottom: 28px;\n      flex-wrap: wrap;\n      gap: 16px;\n    }\n\n    .logo-group {\n      display: flex;\n      align-items: center;\n      gap: 12px;\n    }\n\n    .logo-badge {\n      font-family: var(--mono);\n      font-size: 13px;\n      font-weight: 700;\n      letter-spacing: 0.15em;\n      color: #03080e;\n      background: var(--accent);\n      padding: 6px 12px;\n      border-radius: 4px;\n      text-transform: uppercase;\n      box-shadow: 0 0 16px rgba(100, 240, 200, 0.35);\n    }\n\n    .title-group h1 {\n      font-size: 20px;\n      font-weight: 700;\n      letter-spacing: 0.06em;\n      text-transform: uppercase;\n      font-family: var(--mono);\n      color: var(--text);\n    }\n\n    .title-group p {\n      font-size: 13px;\n      color: var(--dim);\n      margin-top: 2px;\n    }\n\n    .lang-switcher {\n      display: flex;\n      align-items: center;\n      gap: 6px;\n      background: rgba(255, 255, 255, 0.03);\n      border: 1px solid var(--panel-border);\n      border-radius: 4px;\n      padding: 4px;\n    }\n\n    .lang-btn {\n      background: transparent;\n      border: none;\n      color: var(--dim);\n      font-family: var(--mono);\n      font-size: 11px;\n      font-weight: 600;\n      padding: 4px 8px;\n      cursor: pointer;\n      border-radius: 2px;\n      transition: all 0.2s;\n    }\n\n    .lang-btn.active {\n      background: var(--accent);\n      color: #03080e;\n    }\n\n    /* SECTIONS */\n    .section-card {\n      background: var(--panel);\n      border: 1px solid var(--panel-border);\n      border-radius: 8px;\n      padding: 24px;\n      margin-bottom: 24px;\n      box-shadow: 0 8px 32px rgba(0, 0, 0, 0.35);\n      position: relative;\n    }\n\n    .section-header {\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      margin-bottom: 16px;\n      border-bottom: 1px solid rgba(255, 255, 255, 0.06);\n      padding-bottom: 12px;\n    }\n\n    .section-title {\n      font-family: var(--mono);\n      font-size: 14px;\n      font-weight: 700;\n      letter-spacing: 0.08em;\n      text-transform: uppercase;\n      color: var(--accent);\n      display: flex;\n      align-items: center;\n      gap: 8px;\n    }\n\n    .section-desc {\n      font-size: 13px;\n      color: var(--dim);\n      line-height: 1.5;\n      margin-bottom: 18px;\n    }\n\n    /* ACTION BUTTONS (ONE-CLICK) */\n    .action-btn-row {\n      display: flex;\n      flex-wrap: wrap;\n      gap: 10px;\n      margin-bottom: 16px;\n    }\n\n    .click-btn {\n      display: inline-flex;\n      align-items: center;\n      gap: 8px;\n      background: rgba(68, 204, 255, 0.08);\n      border: 1px solid rgba(68, 204, 255, 0.35);\n      color: #d9f7ff;\n      padding: 9px 14px;\n      border-radius: 6px;\n      font-family: var(--mono);\n      font-size: 12px;\n      font-weight: 600;\n      text-decoration: none;\n      cursor: pointer;\n      transition: all 0.2s;\n    }\n\n    .click-btn:hover {\n      background: rgba(68, 204, 255, 0.2);\n      border-color: var(--accent2);\n      transform: translateY(-1px);\n      box-shadow: 0 4px 12px rgba(68, 204, 255, 0.2);\n    }\n\n    .click-btn.tg {\n      background: rgba(41, 169, 234, 0.12);\n      border-color: rgba(41, 169, 234, 0.4);\n      color: #b8e6ff;\n    }\n    .click-btn.tg:hover {\n      background: rgba(41, 169, 234, 0.25);\n      border-color: #29a9ea;\n    }\n\n    .click-btn.gold {\n      background: rgba(255, 184, 76, 0.1);\n      border-color: rgba(255, 184, 76, 0.35);\n      color: #ffe6b8;\n    }\n    .click-btn.gold:hover {\n      background: rgba(255, 184, 76, 0.22);\n      border-color: var(--warn);\n    }\n\n    /* FORM ELEMENTS */\n    .form-grid {\n      display: grid;\n      grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));\n      gap: 16px;\n    }\n\n    .form-group {\n      display: flex;\n      flex-direction: column;\n      gap: 6px;\n    }\n\n    .form-label {\n      font-family: var(--mono);\n      font-size: 11px;\n      font-weight: 600;\n      letter-spacing: 0.06em;\n      text-transform: uppercase;\n      color: var(--dim);\n    }\n\n    .form-input, .form-select {\n      background: rgba(3, 8, 14, 0.85);\n      border: 1px solid rgba(255, 255, 255, 0.12);\n      border-radius: 4px;\n      color: var(--text);\n      font-family: var(--mono);\n      font-size: 13px;\n      padding: 10px 12px;\n      outline: none;\n      transition: all 0.2s;\n      width: 100%;\n    }\n\n    .form-input:focus, .form-select:focus {\n      border-color: var(--accent);\n      box-shadow: 0 0 10px rgba(100, 240, 200, 0.25);\n    }\n\n    .form-select option {\n      background: #060e16;\n      color: #fff;\n    }\n\n    /* TEST BUTTON & STATUS */\n    .test-btn-wrap {\n      display: flex;\n      align-items: center;\n      gap: 12px;\n      margin-top: 14px;\n    }\n\n    .test-btn {\n      background: rgba(100, 240, 200, 0.1);\n      border: 1px solid var(--accent);\n      color: var(--accent);\n      padding: 8px 14px;\n      font-family: var(--mono);\n      font-size: 12px;\n      font-weight: 600;\n      cursor: pointer;\n      border-radius: 4px;\n      transition: all 0.2s;\n    }\n\n    .test-btn:hover {\n      background: var(--accent);\n      color: #03080e;\n    }\n\n    .test-status {\n      font-family: var(--mono);\n      font-size: 12px;\n      font-weight: 500;\n    }\n\n    .test-status.ok { color: var(--accent); }\n    .test-status.err { color: var(--danger); }\n    .test-status.loading { color: var(--warn); }\n\n    /* OSINT SOURCE CARDS */\n    .source-list {\n      display: grid;\n      grid-template-columns: 1fr;\n      gap: 12px;\n    }\n\n    .source-card {\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      background: rgba(255, 255, 255, 0.02);\n      border: 1px solid rgba(255, 255, 255, 0.06);\n      padding: 12px 16px;\n      border-radius: 6px;\n      gap: 16px;\n      flex-wrap: wrap;\n    }\n\n    .source-info {\n      flex: 1;\n      min-width: 240px;\n    }\n\n    .source-name {\n      font-family: var(--mono);\n      font-size: 13px;\n      font-weight: 700;\n      color: var(--text);\n    }\n\n    .source-sub {\n      font-size: 12px;\n      color: var(--dim);\n      margin-top: 2px;\n    }\n\n    .source-input-wrap {\n      flex: 1;\n      min-width: 240px;\n    }\n\n    /* SECRET FIELDS: masked, with an animated eye to reveal */\n    .secret-wrap { position: relative; width: 100%; }\n    .secret-wrap .form-input { padding-right: 44px; }\n    .secret-eye {\n      position: absolute;\n      top: 50%;\n      right: 6px;\n      transform: translateY(-50%);\n      width: 32px;\n      height: 32px;\n      display: grid;\n      place-items: center;\n      padding: 0;\n      background: transparent;\n      border: 0;\n      border-radius: 4px;\n      color: var(--dim);\n      cursor: pointer;\n      transition: color 0.2s, background 0.2s;\n    }\n    .secret-eye:hover, .secret-eye:focus-visible { color: var(--accent); background: rgba(100, 240, 200, 0.08); outline: none; }\n    .secret-eye[aria-pressed=\"true\"] { color: var(--accent); }\n    .secret-eye svg { width: 20px; height: 20px; overflow: visible; }\n    .secret-eye .lid, .secret-eye .pupil { transform-box: fill-box; transform-origin: center; }\n    .secret-eye .pupil { transition: transform 0.25s ease; }\n    .secret-eye .slash { stroke-dasharray: 26; stroke-dashoffset: 26; transition: stroke-dashoffset 0.3s ease; }\n    /* revealed: the eye is crossed out (click hides it again) */\n    .secret-eye[aria-pressed=\"true\"] .slash { stroke-dashoffset: 0; }\n    .secret-eye[aria-pressed=\"true\"] .pupil { transform: scale(0.55); }\n    .secret-eye.blink .lid { animation: eye-blink 0.35s ease; }\n    @keyframes eye-blink { 0%, 100% { transform: scaleY(1); } 45% { transform: scaleY(0.1); } }\n    @media (prefers-reduced-motion: reduce) {\n      .secret-eye .pupil, .secret-eye .slash { transition: none; }\n      .secret-eye.blink .lid { animation: none; }\n    }\n\n    /* BOTTOM SAVE BAR */\n    .footer-bar {\n      position: fixed;\n      bottom: 0;\n      left: 0;\n      right: 0;\n      background: rgba(4, 12, 20, 0.95);\n      backdrop-filter: blur(20px);\n      border-top: 1px solid var(--panel-border);\n      padding: 14px 24px;\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      z-index: 100;\n      box-shadow: 0 -8px 24px rgba(0, 0, 0, 0.5);\n    }\n\n    .footer-info {\n      font-family: var(--mono);\n      font-size: 12px;\n      color: var(--dim);\n    }\n\n    .footer-actions {\n      display: flex;\n      align-items: center;\n      gap: 12px;\n    }\n\n    .save-btn {\n      background: var(--accent);\n      color: #03080e;\n      border: none;\n      font-family: var(--mono);\n      font-size: 14px;\n      font-weight: 700;\n      letter-spacing: 0.05em;\n      padding: 10px 22px;\n      border-radius: 4px;\n      cursor: pointer;\n      box-shadow: 0 0 16px rgba(100, 240, 200, 0.4);\n      transition: all 0.2s;\n    }\n\n    .save-btn:hover {\n      background: #7affd8;\n      box-shadow: 0 0 24px rgba(100, 240, 200, 0.6);\n      transform: translateY(-1px);\n    }\n\n    .dashboard-btn {\n      background: transparent;\n      border: 1px solid var(--accent2);\n      color: var(--accent2);\n      font-family: var(--mono);\n      font-size: 13px;\n      font-weight: 600;\n      padding: 9px 18px;\n      border-radius: 4px;\n      text-decoration: none;\n      transition: all 0.2s;\n    }\n\n    .dashboard-btn:hover {\n      background: rgba(68, 204, 255, 0.15);\n      color: #fff;\n    }\n\n    /* BANNER */\n    .banner {\n      display: none;\n      padding: 14px 18px;\n      border-radius: 6px;\n      margin-bottom: 20px;\n      font-family: var(--mono);\n      font-size: 13px;\n      animation: fadeIn 0.3s ease;\n    }\n    .banner.show { display: block; }\n    .banner.success {\n      background: rgba(100, 240, 200, 0.12);\n      border: 1px solid var(--accent);\n      color: var(--accent);\n    }\n    .banner.error {\n      background: rgba(255, 95, 99, 0.12);\n      border: 1px solid var(--danger);\n      color: #ffd8d9;\n    }\n\n    /* MODAL OVERLAY */\n    .modal-overlay {\n      display: none;\n      position: fixed;\n      inset: 0;\n      background: rgba(3, 8, 14, 0.88);\n      backdrop-filter: blur(14px);\n      z-index: 9999;\n      align-items: center;\n      justify-content: center;\n      padding: 20px;\n      animation: fadeIn 0.25s ease;\n    }\n    .modal-overlay.show { display: flex; }\n    .modal-card {\n      background: #06121f;\n      border: 1px solid var(--accent);\n      border-radius: 12px;\n      max-width: 520px;\n      width: 100%;\n      padding: 32px 24px;\n      text-align: center;\n      box-shadow: 0 0 50px rgba(100, 240, 200, 0.25);\n      animation: scaleUp 0.25s ease;\n    }\n    .modal-icon {\n      font-size: 48px;\n      margin-bottom: 14px;\n      display: inline-block;\n    }\n    .modal-title {\n      font-family: var(--mono);\n      font-size: 20px;\n      font-weight: 700;\n      color: var(--accent);\n      margin-bottom: 8px;\n      text-transform: uppercase;\n      letter-spacing: 0.05em;\n    }\n    .modal-desc {\n      font-size: 14px;\n      color: var(--text);\n      line-height: 1.5;\n      margin-bottom: 16px;\n    }\n    .modal-countdown {\n      font-family: var(--mono);\n      font-size: 14px;\n      font-weight: 600;\n      color: var(--accent2);\n      background: rgba(68, 204, 255, 0.08);\n      border: 1px solid rgba(68, 204, 255, 0.25);\n      padding: 10px 16px;\n      border-radius: 6px;\n      margin-bottom: 22px;\n      display: inline-block;\n    }\n    .modal-actions {\n      display: flex;\n      justify-content: center;\n      gap: 12px;\n      flex-wrap: wrap;\n    }\n    @keyframes scaleUp { from { transform: scale(0.92); opacity: 0; } to { transform: scale(1); opacity: 1; } }\n\n    @keyframes fadeIn { from { opacity: 0; transform: translateY(-6px); } to { opacity: 1; transform: translateY(0); } }\n\n    @media (max-width: 768px) {\n      .footer-bar { flex-direction: column; gap: 10px; align-items: stretch; }\n      .footer-actions { justify-content: space-between; }\n    }\n  </style>\n</head>\n<body>\n\n  <div class=\"container\">\n    <!-- HEADER -->\n    <header>\n      <div class=\"logo-group\">\n        <div class=\"logo-badge\">CRUCIX</div>\n        <div class=\"title-group\">\n          <h1 id=\"i18n-header-title\">Beállító Központ</h1>\n          <p id=\"i18n-header-sub\">Konfiguráld a kulcsokat, értesítéseket és az AI motort 1 kattintással</p>\n        </div>\n      </div>\n      <div class=\"lang-switcher\">\n        <button class=\"lang-btn\" data-lang=\"hu\" onclick=\"switchLang('hu')\">HU</button>\n        <button class=\"lang-btn\" data-lang=\"en\" onclick=\"switchLang('en')\">EN</button>\n        <button class=\"lang-btn\" data-lang=\"fr\" onclick=\"switchLang('fr')\">FR</button>\n      </div>\n    </header>\n\n    <!-- NOTIFICATION BANNER -->\n    <div id=\"statusBanner\" class=\"banner\"></div>\n\n    <form id=\"setupForm\" onsubmit=\"event.preventDefault(); saveConfig();\">\n\n      <!-- 1. TELEGRAM -->\n      <div class=\"section-card\">\n        <div class=\"section-header\">\n          <div class=\"section-title\">\n            <span>📱</span> <span id=\"i18n-tg-title\">Telegram Értesítések & Távvezérlés</span>\n          </div>\n        </div>\n        <p class=\"section-desc\" id=\"i18n-tg-desc\">\n          A Crucix valós idejű riasztásokat küld Telegramra (földrengések, piaci zuhanás, katonai eszkaláció), és válaszol parancsokra (/brief, /status, /sweep, /alerts).\n        </p>\n\n        <!-- 1-CLICK ACTION BUTTONS -->\n        <div class=\"action-btn-row\">\n          <a href=\"https://t.me/BotFather\" target=\"_blank\" rel=\"noopener\" class=\"click-btn tg\">\n            <span>🤖</span> <strong id=\"i18n-tg-btn1\">1. @BotFather Megnyitása (Új bot)</strong>\n          </a>\n          <a href=\"https://t.me/userinfobot\" target=\"_blank\" rel=\"noopener\" class=\"click-btn tg\">\n            <span>🆔</span> <strong id=\"i18n-tg-btn2\">2. @userinfobot Megnyitása (Chat ID)</strong>\n          </a>\n        </div>\n\n        <div class=\"form-grid\">\n          <div class=\"form-group\">\n            <label class=\"form-label\" for=\"TELEGRAM_BOT_TOKEN\">Telegram Bot Token</label>\n            <input type=\"text\" id=\"TELEGRAM_BOT_TOKEN\" name=\"TELEGRAM_BOT_TOKEN\" class=\"form-input\" placeholder=\"pl. 7123456789:AAFlkjhGFD...\" autocomplete=\"off\">\n          </div>\n          <div class=\"form-group\">\n            <label class=\"form-label\" for=\"TELEGRAM_CHAT_ID\">Telegram Chat ID</label>\n            <input type=\"text\" id=\"TELEGRAM_CHAT_ID\" name=\"TELEGRAM_CHAT_ID\" class=\"form-input\" placeholder=\"pl. 123456789\" autocomplete=\"off\">\n          </div>\n        </div>\n\n        <div class=\"test-btn-wrap\">\n          <button type=\"button\" class=\"test-btn\" onclick=\"testTelegram()\">⚡ <span id=\"i18n-tg-test\">Telegram Kapcsolat Tesztelése</span></button>\n          <span id=\"tgTestStatus\" class=\"test-status\"></span>\n        </div>\n      </div>\n\n      <!-- 2. DISCORD -->\n      <div class=\"section-card\">\n        <div class=\"section-header\">\n          <div class=\"section-title\">\n            <span>💬</span> <span id=\"i18n-dc-title\">Discord Webhook Riasztások</span>\n          </div>\n        </div>\n        <p class=\"section-desc\" id=\"i18n-dc-desc\">\n          Közvetlen értesítések küldése egy Discord szervercsatornára. Nincs szükség bot fejlesztésre, elég a csatorna beállításokból kimásolni a Webhook URL-t.\n        </p>\n\n        <div class=\"form-group\" style=\"margin-bottom: 12px;\">\n          <label class=\"form-label\" for=\"DISCORD_WEBHOOK_URL\">Discord Webhook URL</label>\n          <input type=\"url\" id=\"DISCORD_WEBHOOK_URL\" name=\"DISCORD_WEBHOOK_URL\" class=\"form-input\" placeholder=\"https://discord.com/api/webhooks/...\" autocomplete=\"off\">\n        </div>\n\n        <div class=\"test-btn-wrap\">\n          <button type=\"button\" class=\"test-btn\" onclick=\"testDiscord()\">⚡ <span id=\"i18n-dc-test\">Discord Webhook Tesztelése</span></button>\n          <span id=\"dcTestStatus\" class=\"test-status\"></span>\n        </div>\n      </div>\n\n      <!-- 3. AI / LLM ENGINE -->\n      <div class=\"section-card\">\n        <div class=\"section-header\">\n          <div class=\"section-title\">\n            <span>🤖</span> <span id=\"i18n-ai-title\">Mesterséges Intelligencia (AI / LLM) Motor</span>\n          </div>\n        </div>\n        <p class=\"section-desc\" id=\"i18n-ai-desc\">\n          Az AI vezetői jelentéseket, szöveges elemzéseket és piaci kereskedési ötleteket generál a 71 adatforrás alapján.\n        </p>\n\n        <div class=\"form-grid\" style=\"margin-bottom: 16px;\">\n          <div class=\"form-group\">\n            <label class=\"form-label\" for=\"LLM_PROVIDER\" id=\"i18n-ai-provider-label\">AI Szolgáltató</label>\n            <select id=\"LLM_PROVIDER\" name=\"LLM_PROVIDER\" class=\"form-select\" onchange=\"updateAiFields()\">\n              <option value=\"cursor\">Cursor IDE (Beépített modell — Zero-config, ingyenes)</option>\n              <option value=\"ollama\">Ollama (Helyi, 100% privát, ingyenes)</option>\n              <option value=\"openai-compatible\">OpenAI-kompatibilis (LM Studio, llama.cpp, vLLM)</option>\n              <option value=\"anthropic\">Anthropic Claude (Claude 3.5 / 3.7 Sonnet)</option>\n              <option value=\"openai\">OpenAI (GPT-4o, GPT-5)</option>\n              <option value=\"gemini\">Google Gemini (Gemini 2.5 Flash / Pro)</option>\n              <option value=\"\">Szabályalapú (AI nélkül, azonnali és ingyenes)</option>\n            </select>\n          </div>\n          <div class=\"form-group\" id=\"aiModelGroup\">\n            <label class=\"form-label\" for=\"LLM_MODEL\">Modell Felülbírálás</label>\n            <input type=\"text\" id=\"LLM_MODEL\" name=\"LLM_MODEL\" class=\"form-input\" placeholder=\"Alapértelmezett modell használata\">\n          </div>\n        </div>\n\n        <!-- Dynamic AI Key & URL fields -->\n        <div id=\"aiDynamicFields\" class=\"form-grid\" style=\"margin-bottom: 14px;\">\n          <div class=\"form-group\" id=\"aiKeyGroup\">\n            <label class=\"form-label\" for=\"LLM_API_KEY\">AI API Kulcs</label>\n            <input type=\"password\" id=\"LLM_API_KEY\" name=\"LLM_API_KEY\" class=\"form-input\" placeholder=\"sk-...\" autocomplete=\"off\">\n          </div>\n          <div class=\"form-group\" id=\"aiUrlGroup\">\n            <label class=\"form-label\" for=\"LLM_BASE_URL\">API Base URL</label>\n            <input type=\"url\" id=\"LLM_BASE_URL\" name=\"LLM_BASE_URL\" class=\"form-input\" placeholder=\"http://localhost:11434\">\n          </div>\n        </div>\n\n        <div class=\"action-btn-row\" id=\"aiKeyButtons\">\n          <a href=\"https://console.anthropic.com/settings/keys\" target=\"_blank\" rel=\"noopener\" class=\"click-btn gold\" id=\"btnAnthropicKey\">\n            <span>🔑</span> <strong>Anthropic Claude API Kulcs Kérése</strong>\n          </a>\n          <a href=\"https://platform.openai.com/api-keys\" target=\"_blank\" rel=\"noopener\" class=\"click-btn gold\" id=\"btnOpenAiKey\">\n            <span>🔑</span> <strong>OpenAI API Kulcs Kérése</strong>\n          </a>\n          <a href=\"https://aistudio.google.com/app/apikey\" target=\"_blank\" rel=\"noopener\" class=\"click-btn gold\" id=\"btnGeminiKey\">\n            <span>🔑</span> <strong>Google Gemini API Kulcs Kérése</strong>\n          </a>\n        </div>\n      </div>\n\n      <!-- 4. INGYENES OSINT KULCSOK -->\n      <div class=\"section-card\">\n        <div class=\"section-header\">\n          <div class=\"section-title\">\n            <span>🌐</span> <span id=\"i18n-osint-title\">Ingyenes Geopolitikai & OSINT API Kulcsok</span>\n          </div>\n        </div>\n        <p class=\"section-desc\" id=\"i18n-osint-desc\">\n          A források zöme (USGS, RSS, kiberbiztonság, IODA) kulcs nélkül is működik. OpenSky OAuth2 klienst kér; BLS kulccsal 500 lekérés/nap (nélküle ~25). Az alábbi mezők növelik a frissítést:\n        </p>\n\n        <div class=\"source-list\">\n          <!-- FIRMS -->\n          <div class=\"source-card\">\n            <div class=\"source-info\">\n              <div class=\"source-name\">🔥 NASA FIRMS (Műholdas Tűz & Hőtérkép)</div>\n              <div class=\"source-sub\">Ingyenes műholdas érzékelés Közel-Keleten, Ukrajnában</div>\n            </div>\n            <a href=\"https://firms.modaps.eosdis.nasa.gov/api\" target=\"_blank\" rel=\"noopener\" class=\"click-btn\">\n              <span>🔑</span> <strong>Kulcs kérése (Kattints ide)</strong>\n            </a>\n            <div class=\"source-input-wrap\">\n              <input type=\"text\" id=\"FIRMS_MAP_KEY\" name=\"FIRMS_MAP_KEY\" class=\"form-input\" placeholder=\"FIRMS_MAP_KEY\" autocomplete=\"off\">\n            </div>\n          </div>\n\n          <!-- FRED -->\n          <div class=\"source-card\">\n            <div class=\"source-info\">\n              <div class=\"source-name\">📊 FRED (Amerikai Jegybanki Makroadatok)</div>\n              <div class=\"source-sub\">Kamatok, infláció, VIX, kincstárjegy hozamok</div>\n            </div>\n            <a href=\"https://fred.stlouisfed.org/docs/api/api_key.html\" target=\"_blank\" rel=\"noopener\" class=\"click-btn\">\n              <span>🔑</span> <strong>Kulcs kérése (Kattints ide)</strong>\n            </a>\n            <div class=\"source-input-wrap\">\n              <input type=\"text\" id=\"FRED_API_KEY\" name=\"FRED_API_KEY\" class=\"form-input\" placeholder=\"FRED_API_KEY\" autocomplete=\"off\">\n            </div>\n          </div>\n\n          <!-- BLS -->\n          <div class=\"source-card\">\n            <div class=\"source-info\">\n              <div class=\"source-name\">📉 BLS (Munkaügyi Statisztika: CPI, munkanélküliség)</div>\n              <div class=\"source-sub\">Kulcs nélkül ~25 lekérés/nap (v1); kulccsal 500/nap (v2). A Crucix 12 órát cache-el</div>\n            </div>\n            <a href=\"https://data.bls.gov/registrationEngine/\" target=\"_blank\" rel=\"noopener\" class=\"click-btn\">\n              <span>🔑</span> <strong>Ingyenes kulcs (Kattints ide)</strong>\n            </a>\n            <div class=\"source-input-wrap\">\n              <input type=\"text\" id=\"BLS_API_KEY\" name=\"BLS_API_KEY\" class=\"form-input\" placeholder=\"BLS_API_KEY\" autocomplete=\"off\">\n            </div>\n          </div>\n\n          <!-- OPENSKY -->\n          <div class=\"source-card\">\n            <div class=\"source-info\">\n              <div class=\"source-name\">✈️ OpenSky (ADS-B repülési hotspotok)</div>\n              <div class=\"source-sub\">Anonim: 400 credit/nap; OAuth2 klienssel: 4000/nap, frissítés 15 percenként</div>\n            </div>\n            <a href=\"https://opensky-network.org/my-opensky/account\" target=\"_blank\" rel=\"noopener\" class=\"click-btn\">\n              <span>🔑</span> <strong>API client létrehozása</strong>\n            </a>\n            <div class=\"source-input-wrap\" style=\"display:flex;flex-direction:column;gap:0.5rem\">\n              <input type=\"text\" id=\"OPENSKY_CLIENT_ID\" name=\"OPENSKY_CLIENT_ID\" class=\"form-input\" placeholder=\"OPENSKY_CLIENT_ID (credentials.json → clientId)\" autocomplete=\"off\">\n              <input type=\"password\" id=\"OPENSKY_CLIENT_SECRET\" name=\"OPENSKY_CLIENT_SECRET\" class=\"form-input\" placeholder=\"OPENSKY_CLIENT_SECRET (clientSecret)\" autocomplete=\"off\">\n            </div>\n          </div>\n\n          <!-- EIA -->\n          <div class=\"source-card\">\n            <div class=\"source-info\">\n              <div class=\"source-name\">⚡ EIA (Globális Energia, Olaj & Gáz)</div>\n              <div class=\"source-sub\">WTI, Brent, földgáz készletinformációk</div>\n            </div>\n            <a href=\"https://api.eia.gov/register\" target=\"_blank\" rel=\"noopener\" class=\"click-btn\">\n              <span>🔑</span> <strong>Regisztráció (Kattints ide)</strong>\n            </a>\n            <div class=\"source-input-wrap\">\n              <input type=\"text\" id=\"EIA_API_KEY\" name=\"EIA_API_KEY\" class=\"form-input\" placeholder=\"EIA_API_KEY\" autocomplete=\"off\">\n            </div>\n          </div>\n\n          <!-- FMP -->\n          <div class=\"source-card\">\n            <div class=\"source-info\">\n              <div class=\"source-name\">📈 Financial Modeling Prep (Részvények, Indexek, Devizák)</div>\n              <div class=\"source-sub\">Napi sáv, 52 hetes sáv, forgalom, piaci kapitalizáció; 250 hívás/nap ingyenes (Crucix: ~192)</div>\n            </div>\n            <a href=\"https://site.financialmodelingprep.com/register\" target=\"_blank\" rel=\"noopener\" class=\"click-btn\">\n              <span>🔑</span> <strong>Regisztráció (Kattints ide)</strong>\n            </a>\n            <div class=\"source-input-wrap\">\n              <input type=\"text\" id=\"FMP_API_KEY\" name=\"FMP_API_KEY\" class=\"form-input\" placeholder=\"FMP_API_KEY\" autocomplete=\"off\">\n            </div>\n          </div>\n\n          <!-- FINNHUB -->\n          <div class=\"source-card\">\n            <div class=\"source-info\">\n              <div class=\"source-name\">💹 Finnhub (Második részvényforrás)</div>\n              <div class=\"source-sub\">Amerikai tőzsdei részvények, 60 hívás/perc ingyenes</div>\n            </div>\n            <a href=\"https://finnhub.io/register\" target=\"_blank\" rel=\"noopener\" class=\"click-btn\">\n              <span>🔑</span> <strong>Regisztráció (Kattints ide)</strong>\n            </a>\n            <div class=\"source-input-wrap\">\n              <input type=\"text\" id=\"FINNHUB_API_KEY\" name=\"FINNHUB_API_KEY\" class=\"form-input\" placeholder=\"FINNHUB_API_KEY\" autocomplete=\"off\">\n            </div>\n          </div>\n\n          <!-- BASE CURRENCY -->\n          <div class=\"source-card\">\n            <div class=\"source-info\">\n              <div class=\"source-name\">💱 Alap deviza (Base currency)</div>\n              <div class=\"source-sub\">Az árfolyam-keresztek ehhez viszonyítva jelennek meg; a dashboardon felhasználónként átállítható</div>\n            </div>\n            <div class=\"source-input-wrap\">\n              <select id=\"CRUCIX_BASE_CURRENCY\" name=\"CRUCIX_BASE_CURRENCY\" class=\"form-input\">\n                <option value=\"USD\">USD</option><option value=\"EUR\">EUR</option><option value=\"GBP\">GBP</option>\n                <option value=\"HUF\">HUF</option><option value=\"JPY\">JPY</option><option value=\"CHF\">CHF</option>\n                <option value=\"CAD\">CAD</option><option value=\"AUD\">AUD</option><option value=\"CNY\">CNY</option>\n              </select>\n            </div>\n          </div>\n\n          <!-- AISSTREAM -->\n          <div class=\"source-card\">\n            <div class=\"source-info\">\n              <div class=\"source-name\">🚢 AISStream (Élő Tengeri Hajóforgalom)</div>\n              <div class=\"source-sub\">11 tengeri szoros és fojtópont (Hormuz, Szuez, Malakka)</div>\n            </div>\n            <a href=\"https://aisstream.io/account\" target=\"_blank\" rel=\"noopener\" class=\"click-btn\">\n              <span>🔑</span> <strong>Belépés GitHub-bal</strong>\n            </a>\n            <div class=\"source-input-wrap\">\n              <input type=\"text\" id=\"AISSTREAM_API_KEY\" name=\"AISSTREAM_API_KEY\" class=\"form-input\" placeholder=\"AISSTREAM_API_KEY\" autocomplete=\"off\">\n            </div>\n          </div>\n\n          <!-- CLOUDFLARE -->\n          <div class=\"source-card\">\n            <div class=\"source-info\">\n              <div class=\"source-name\">🌐 Cloudflare Radar (Internetkimaradások)</div>\n              <div class=\"source-sub\">Globális internetforgalmi anomáliák</div>\n            </div>\n            <a href=\"https://dash.cloudflare.com/profile/api-tokens\" target=\"_blank\" rel=\"noopener\" class=\"click-btn\">\n              <span>🔑</span> <strong>Token készítése</strong>\n            </a>\n            <div class=\"source-input-wrap\">\n              <input type=\"text\" id=\"CLOUDFLARE_API_TOKEN\" name=\"CLOUDFLARE_API_TOKEN\" class=\"form-input\" placeholder=\"CLOUDFLARE_API_TOKEN\" autocomplete=\"off\">\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <!-- 5. SERVER SETTINGS -->\n      <div class=\"section-card\">\n        <div class=\"section-header\">\n          <div class=\"section-title\">\n            <span>🖥️</span> <span id=\"i18n-srv-title\">Dashboard & Hálózat</span>\n          </div>\n        </div>\n        <div class=\"form-grid\">\n          <div class=\"form-group\">\n            <label class=\"form-label\" for=\"PORT\">Dashboard Port</label>\n            <input type=\"number\" id=\"PORT\" name=\"PORT\" class=\"form-input\" value=\"3117\" min=\"1024\" max=\"65535\">\n          </div>\n          <div class=\"form-group\">\n            <label class=\"form-label\" for=\"HOST\">Hálózati Cím (HOST)</label>\n            <select id=\"HOST\" name=\"HOST\" class=\"form-select\">\n              <option value=\"127.0.0.1\">127.0.0.1 (Csak a helyi gépről érhető el — Biztonságos)</option>\n              <option value=\"0.0.0.0\">0.0.0.0 (Elérhető a helyi hálózatról / LAN-ról is)</option>\n            </select>\n          </div>\n          <div class=\"form-group\">\n            <label class=\"form-label\" for=\"CRUCIX_LANG\">Alapértelmezett Nyelv</label>\n            <select id=\"CRUCIX_LANG\" name=\"CRUCIX_LANG\" class=\"form-select\" onchange=\"switchLang(this.value)\">\n              <option value=\"hu\">Magyar (hu)</option>\n              <option value=\"en\">English (en)</option>\n              <option value=\"fr\">Français (fr)</option>\n            </select>\n          </div>\n        </div>\n      </div>\n\n      <div style=\"height: 40px;\"></div>\n\n      <!-- FOOTER SAVE BAR -->\n      <div class=\"footer-bar\">\n        <div class=\"footer-info\">\n          <span>📁 Célkonfiguráció: </span><strong id=\"targetEnvDisplay\">~/.crucix/.env</strong>\n        </div>\n        <div class=\"footer-actions\">\n          <button type=\"button\" class=\"dashboard-btn\" style=\"border-color: rgba(255,255,255,0.2); color: var(--dim);\" onclick=\"exitSetup()\">🚪 <span id=\"i18n-exit-btn\">Bezárás & Kilépés</span></button>\n          <a href=\"/\" class=\"dashboard-btn\" id=\"i18n-open-dash\">Irány a Vezérlőpult</a>\n          <button type=\"submit\" class=\"save-btn\" id=\"i18n-save-btn\">💾 Beállítások Mentése</button>\n        </div>\n      </div>\n\n    </form>\n  </div>\n\n  <!-- EXIT & COMPLETION MODAL -->\n  <div id=\"exitModal\" class=\"modal-overlay\">\n    <div class=\"modal-card\">\n      <div class=\"modal-icon\">🎉</div>\n      <h2 class=\"modal-title\" id=\"exitModalTitle\">Beállítások Elmentve!</h2>\n      <p class=\"modal-desc\" id=\"exitModalDesc\">A konfiguráció sikeresen frissült a .env fájlban.</p>\n      <div class=\"modal-countdown\" id=\"exitCountdown\">Automatikus bezárás 3 másodperc múlva...</div>\n      <div class=\"modal-actions\">\n        <button type=\"button\" class=\"save-btn\" id=\"exitModalCloseBtn\" onclick=\"closeWindowNow()\">🚪 <span id=\"i18n-close-now\">Ablak Bezárása Most</span></button>\n        <button type=\"button\" class=\"dashboard-btn\" id=\"exitModalStayBtn\" onclick=\"cancelExitModal()\"><span id=\"i18n-stay-page\">Maradok az oldalon</span></button>\n        <a href=\"/\" class=\"dashboard-btn\" id=\"exitModalDashBtn\" style=\"display:none;\">Irány a Vezérlőpult</a>\n      </div>\n    </div>\n  </div>\n\n  <script>\n    const I18N = {\n      hu: {\n        headerTitle: \"Beállító Központ\",\n        headerSub: \"Konfiguráld a kulcsokat, értesítéseket és az AI motort 1 kattintással\",\n        tgTitle: \"Telegram Értesítések & Távvezérlés\",\n        tgDesc: \"A Crucix valós idejű riasztásokat küld Telegramra (földrengések, piaci zuhanás, katonai eszkaláció), és válaszol parancsokra (/brief, /status, /sweep, /alerts).\",\n        tgBtn1: \"1. @BotFather Megnyitása (Új bot)\",\n        tgBtn2: \"2. @userinfobot Megnyitása (Chat ID)\",\n        tgTest: \"Telegram Kapcsolat Tesztelése\",\n        dcTitle: \"Discord Webhook Riasztások\",\n        dcDesc: \"Közvetlen értesítések küldése egy Discord szervercsatornára. Nincs szükség bot fejlesztésre, elég a csatorna beállításokból kimásolni a Webhook URL-t.\",\n        dcTest: \"Discord Webhook Tesztelése\",\n        aiTitle: \"Mesterséges Intelligencia (AI / LLM) Motor\",\n        aiDesc: \"Az AI vezetői jelentéseket, szöveges elemzéseket és piaci kereskedési ötleteket generál a 71 adatforrás alapján.\",\n        osintTitle: \"Ingyenes Geopolitikai & OSINT API Kulcsok\",\n        osintDesc: \"A források zöme (USGS, RSS, kiberbiztonság, IODA) kulcs nélkül is működik. OpenSky OAuth2 klienst kér; BLS kulccsal 500 lekérés/nap (nélküle ~25). Az alábbi mezők növelik a frissítést:\",\n        srvTitle: \"Dashboard & Hálózat\",\n        openDash: \"Irány a Vezérlőpult\",\n        saveBtn: \"💾 Beállítások Mentése\",\n        savedTitle: \"Beállítások Sikeresen Mentve!\",\n        savedDesc: \"A konfiguráció frissült a .env fájlban.\",\n        savedExitDesc: \"A beállító varázsló befejeződött, a szerver leáll.\",\n        closingIn: \"Automatikus bezárás {sec} másodperc múlva...\",\n        closeNow: \"Ablak Bezárása Most\",\n        stayOnPage: \"Maradok az oldalon\",\n        exitBtn: \"Bezárás & Kilépés\",\n        manualClose: \"A beállító varázsló leállt. Nyugodtan zárd be ezt a böngészőfület (Ctrl+W)!\",\n      },\n      en: {\n        headerTitle: \"Setup & Configuration Center\",\n        headerSub: \"Configure API keys, notifications, and AI engine with 1 click\",\n        tgTitle: \"Telegram Alerts & Remote Bot\",\n        tgDesc: \"Crucix dispatches real-time alerts to Telegram (earthquakes, market shocks, military escalation) and replies to commands (/brief, /status, /sweep, /alerts).\",\n        tgBtn1: \"1. Open @BotFather (Create bot)\",\n        tgBtn2: \"2. Open @userinfobot (Get Chat ID)\",\n        tgTest: \"Test Telegram Connection\",\n        dcTitle: \"Discord Webhook Alerts\",\n        dcDesc: \"Push intelligence alerts directly to your Discord server channel using an incoming webhook.\",\n        dcTest: \"Test Discord Webhook\",\n        aiTitle: \"Artificial Intelligence (AI / LLM) Engine\",\n        aiDesc: \"Generates cited executive briefings, automated trade ideas, and multi-domain syntheses.\",\n        osintTitle: \"Free Geopolitical & OSINT API Keys\",\n        osintDesc: \"Most sources (USGS, RSS, cyber, IODA) work without keys. OpenSky takes an OAuth2 client; BLS key raises the daily cap from ~25 to 500. These fields boost freshness:\",\n        srvTitle: \"Dashboard & Network\",\n        openDash: \"Open Dashboard\",\n        saveBtn: \"💾 Save Configuration\",\n        savedTitle: \"Settings Saved Successfully!\",\n        savedDesc: \"Configuration updated in .env.\",\n        savedExitDesc: \"Setup assistant completed, shutting down server.\",\n        closingIn: \"Closing automatically in {sec}s...\",\n        closeNow: \"Close Window Now\",\n        stayOnPage: \"Stay on Page\",\n        exitBtn: \"Close & Exit\",\n        manualClose: \"Setup server stopped. You can safely close this browser tab (Ctrl+W)!\",\n      },\n      fr: {\n        headerTitle: \"Centre de Configuration\",\n        headerSub: \"Configurez les clés, notifications et le moteur IA en 1 clic\",\n        tgTitle: \"Alertes Telegram & Télécommande\",\n        tgDesc: \"Crucix envoie des alertes en temps réel sur Telegram et répond aux commandes (/brief, /status, /sweep, /alerts).\",\n        tgBtn1: \"1. Ouvrir @BotFather (Créer un bot)\",\n        tgBtn2: \"2. Ouvrir @userinfobot (Obtenir Chat ID)\",\n        tgTest: \"Tester la Connexion Telegram\",\n        dcTitle: \"Alertes Webhook Discord\",\n        dcDesc: \"Envoyez des alertes directement sur un canal Discord à l'aide d'un webhook entrant.\",\n        dcTest: \"Tester le Webhook Discord\",\n        aiTitle: \"Moteur d'Intelligence Artificielle (IA / LLM)\",\n        aiDesc: \"Génère des synthèses exécutives et des idées de trading automatiques.\",\n        osintTitle: \"Clés API OSINT Gratuites\",\n        osintDesc: \"La plupart des sources fonctionnent sans clé. OpenSky demande un client OAuth2 ; la clé BLS passe ~25 à 500 requêtes/jour. Ces champs améliorent la fraîcheur :\",\n        srvTitle: \"Tableau de Bord & Réseau\",\n        openDash: \"Ouvrir le Tableau de bord\",\n        saveBtn: \"💾 Enregistrer la Configuration\",\n        savedTitle: \"Paramètres Enregistrés !\",\n        savedDesc: \"Configuration mise à jour dans le fichier .env.\",\n        savedExitDesc: \"L'assistant est terminé, le serveur s'arrête.\",\n        closingIn: \"Fermeture automatique dans {sec}s...\",\n        closeNow: \"Fermer l'onglet maintenant\",\n        stayOnPage: \"Rester sur la page\",\n        exitBtn: \"Fermer & Quitter\",\n        manualClose: \"Serveur arrêté. Vous pouvez fermer cet onglet (Ctrl+W)!\",\n      }\n    };\n\n    let currentLang = 'hu';\n\n    function switchLang(lang) {\n      if (!I18N[lang]) lang = 'hu';\n      currentLang = lang;\n      document.querySelectorAll('.lang-btn').forEach(btn => {\n        btn.classList.toggle('active', btn.dataset.lang === lang);\n      });\n      document.getElementById('CRUCIX_LANG').value = lang;\n      refreshSecretLabels();\n\n      const t = I18N[lang];\n      document.getElementById('i18n-header-title').textContent = t.headerTitle;\n      document.getElementById('i18n-header-sub').textContent = t.headerSub;\n      document.getElementById('i18n-tg-title').textContent = t.tgTitle;\n      document.getElementById('i18n-tg-desc').textContent = t.tgDesc;\n      document.getElementById('i18n-tg-btn1').textContent = t.tgBtn1;\n      document.getElementById('i18n-tg-btn2').textContent = t.tgBtn2;\n      document.getElementById('i18n-tg-test').textContent = t.tgTest;\n      document.getElementById('i18n-dc-title').textContent = t.dcTitle;\n      document.getElementById('i18n-dc-desc').textContent = t.dcDesc;\n      document.getElementById('i18n-dc-test').textContent = t.dcTest;\n      document.getElementById('i18n-ai-title').textContent = t.aiTitle;\n      document.getElementById('i18n-ai-desc').textContent = t.aiDesc;\n      document.getElementById('i18n-osint-title').textContent = t.osintTitle;\n      document.getElementById('i18n-osint-desc').textContent = t.osintDesc;\n      document.getElementById('i18n-srv-title').textContent = t.srvTitle;\n      document.getElementById('i18n-open-dash').textContent = t.openDash;\n      document.getElementById('i18n-save-btn').textContent = t.saveBtn;\n      const exitBtnEl = document.getElementById('i18n-exit-btn');\n      if (exitBtnEl) exitBtnEl.textContent = t.exitBtn;\n      const closeNowEl = document.getElementById('i18n-close-now');\n      if (closeNowEl) closeNowEl.textContent = t.closeNow;\n      const stayPageEl = document.getElementById('i18n-stay-page');\n      if (stayPageEl) stayPageEl.textContent = t.stayOnPage;\n    }\n\n    function showBanner(text, type = 'success') {\n      const banner = document.getElementById('statusBanner');\n      banner.className = `banner show ${type}`;\n      banner.innerHTML = text;\n      window.scrollTo({ top: 0, behavior: 'smooth' });\n    }\n\n    function updateAiFields() {\n      const provider = document.getElementById('LLM_PROVIDER').value;\n      const keyGroup = document.getElementById('aiKeyGroup');\n      const urlGroup = document.getElementById('aiUrlGroup');\n      const buttons = document.getElementById('aiKeyButtons');\n\n      if (provider === 'cursor' || !provider) {\n        keyGroup.style.display = 'none';\n        urlGroup.style.display = 'none';\n        buttons.style.display = 'none';\n      } else if (provider === 'ollama') {\n        keyGroup.style.display = 'none';\n        urlGroup.style.display = 'flex';\n        document.getElementById('LLM_BASE_URL').placeholder = 'http://localhost:11434';\n        buttons.style.display = 'none';\n      } else if (provider === 'openai-compatible') {\n        keyGroup.style.display = 'flex';\n        urlGroup.style.display = 'flex';\n        document.getElementById('LLM_BASE_URL').placeholder = 'http://localhost:1234/v1';\n        buttons.style.display = 'none';\n      } else {\n        keyGroup.style.display = 'flex';\n        urlGroup.style.display = 'none';\n        buttons.style.display = 'flex';\n        document.getElementById('btnAnthropicKey').style.display = provider === 'anthropic' ? 'inline-flex' : 'none';\n        document.getElementById('btnOpenAiKey').style.display = provider === 'openai' ? 'inline-flex' : 'none';\n        document.getElementById('btnGeminiKey').style.display = provider === 'gemini' ? 'inline-flex' : 'none';\n      }\n    }\n\n    async function loadConfig() {\n      try {\n        const res = await fetch('/api/setup/config');\n        if (!res.ok) return;\n        const data = await res.json();\n        if (data.targetEnv) {\n          document.getElementById('targetEnvDisplay').textContent = data.targetEnv;\n        }\n        if (data.values) {\n          for (const [k, v] of Object.entries(data.values)) {\n            const el = document.getElementById(k);\n            if (el && v !== undefined && v !== null) {\n              el.value = v;\n            }\n          }\n          if (data.values.CRUCIX_LANG) {\n            switchLang(data.values.CRUCIX_LANG);\n          }\n        }\n        updateAiFields();\n      } catch (err) {\n        console.warn('Could not load config via API:', err);\n      }\n    }\n\n    async function testTelegram() {\n      const statusEl = document.getElementById('tgTestStatus');\n      const botToken = document.getElementById('TELEGRAM_BOT_TOKEN').value.trim();\n      const chatId = document.getElementById('TELEGRAM_CHAT_ID').value.trim();\n\n      if (!botToken || !chatId) {\n        statusEl.className = 'test-status err';\n        statusEl.textContent = '❌ Kérlek add meg a Bot Tokent és a Chat ID-t!';\n        return;\n      }\n\n      statusEl.className = 'test-status loading';\n      statusEl.textContent = '⏳ Üzenet küldése...';\n\n      try {\n        const res = await fetch('/api/setup/test-telegram', {\n          method: 'POST',\n          headers: { 'Content-Type': 'application/json' },\n          body: JSON.stringify({ botToken, chatId })\n        });\n        const data = await res.json();\n        if (data.ok) {\n          statusEl.className = 'test-status ok';\n          statusEl.textContent = '✅ Sikeres próbaüzenet elküldve! Ellenőrizd a Telegramot!';\n        } else {\n          statusEl.className = 'test-status err';\n          statusEl.textContent = `❌ Hiba: ${data.error || 'Nem sikerült elküldeni'}`;\n        }\n      } catch (err) {\n        statusEl.className = 'test-status err';\n        statusEl.textContent = `❌ Hálózati hiba: ${err.message}`;\n      }\n    }\n\n    async function testDiscord() {\n      const statusEl = document.getElementById('dcTestStatus');\n      const webhookUrl = document.getElementById('DISCORD_WEBHOOK_URL').value.trim();\n\n      if (!webhookUrl) {\n        statusEl.className = 'test-status err';\n        statusEl.textContent = '❌ Kérlek add meg a Discord Webhook URL-t!';\n        return;\n      }\n\n      statusEl.className = 'test-status loading';\n      statusEl.textContent = '⏳ Üzenet küldése...';\n\n      try {\n        const res = await fetch('/api/setup/test-discord', {\n          method: 'POST',\n          headers: { 'Content-Type': 'application/json' },\n          body: JSON.stringify({ webhookUrl })\n        });\n        const data = await res.json();\n        if (data.ok) {\n          statusEl.className = 'test-status ok';\n          statusEl.textContent = '✅ Sikeres próbaüzenet a Discord csatornán!';\n        } else {\n          statusEl.className = 'test-status err';\n          statusEl.textContent = `❌ Hiba: ${data.error || 'Nem sikerült elküldeni'}`;\n        }\n      } catch (err) {\n        statusEl.className = 'test-status err';\n        statusEl.textContent = `❌ Hálózati hiba: ${err.message}`;\n      }\n    }\n\n    async function saveConfig() {\n      const form = document.getElementById('setupForm');\n      const formData = new FormData(form);\n      const updates = {};\n      for (const [k, v] of formData.entries()) {\n        updates[k] = v;\n      }\n\n      // Automatically configure ALERT_NOTIFY_CHANNELS\n      const channels = [];\n      if (updates.TELEGRAM_BOT_TOKEN && updates.TELEGRAM_CHAT_ID) channels.push('telegram');\n      if (updates.DISCORD_WEBHOOK_URL) channels.push('discord');\n      if (channels.length > 0) {\n        updates.ALERT_NOTIFY_CHANNELS = channels.join(',');\n      }\n\n      updates.TRADE_IDEAS_LANG = updates.CRUCIX_LANG || 'hu';\n\n      try {\n        const res = await fetch('/api/setup/save', {\n          method: 'POST',\n          headers: { 'Content-Type': 'application/json' },\n          body: JSON.stringify(updates)\n        });\n        const data = await res.json();\n        if (data.ok) {\n          showExitModal(data);\n        } else {\n          showBanner(`❌ Nem sikerült elmenteni: ${data.error || 'Ismeretlen hiba'}`, 'error');\n        }\n      } catch (err) {\n        showBanner(`❌ Mentési hiba: ${err.message}`, 'error');\n      }\n    }\n\n    let countdownInterval = null;\n\n    function showExitModal(data = {}) {\n      const modal = document.getElementById('exitModal');\n      const title = document.getElementById('exitModalTitle');\n      const desc = document.getElementById('exitModalDesc');\n      const countdown = document.getElementById('exitCountdown');\n      const dashBtn = document.getElementById('exitModalDashBtn');\n      const t = I18N[currentLang] || I18N.hu;\n\n      modal.classList.add('show');\n      title.textContent = t.savedTitle;\n\n      const willExit = Boolean(data.willExit);\n      if (willExit) {\n        desc.textContent = t.savedExitDesc;\n        dashBtn.style.display = 'none';\n      } else {\n        desc.textContent = t.savedDesc;\n        dashBtn.style.display = 'inline-flex';\n      }\n\n      let remaining = 3;\n      countdown.textContent = t.closingIn.replace('{sec}', remaining);\n\n      if (countdownInterval) clearInterval(countdownInterval);\n      countdownInterval = setInterval(() => {\n        remaining--;\n        if (remaining > 0) {\n          countdown.textContent = t.closingIn.replace('{sec}', remaining);\n        } else {\n          clearInterval(countdownInterval);\n          countdownInterval = null;\n          closeWindowNow();\n        }\n      }, 1000);\n    }\n\n    function cancelExitModal() {\n      if (countdownInterval) {\n        clearInterval(countdownInterval);\n        countdownInterval = null;\n      }\n      document.getElementById('exitModal').classList.remove('show');\n      const t = I18N[currentLang] || I18N.hu;\n      showBanner('✅ ' + t.savedDesc, 'success');\n    }\n\n    function closeWindowNow() {\n      if (countdownInterval) {\n        clearInterval(countdownInterval);\n        countdownInterval = null;\n      }\n\n      // Try closing the browser tab\n      try {\n        window.open('', '_self', '');\n        window.close();\n      } catch (e) {}\n      window.close();\n\n      // If browser security prevented window.close(), show clear advice\n      setTimeout(() => {\n        const countdown = document.getElementById('exitCountdown');\n        const t = I18N[currentLang] || I18N.hu;\n        if (countdown) {\n          countdown.innerHTML = '✅ ' + t.manualClose;\n          countdown.style.background = 'rgba(100, 240, 200, 0.12)';\n          countdown.style.borderColor = 'var(--accent)';\n          countdown.style.color = 'var(--accent)';\n        }\n      }, 350);\n    }\n\n    async function exitSetup() {\n      try {\n        await fetch('/api/setup/exit', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}' });\n      } catch {}\n      closeWindowNow();\n    }\n\n    // API keys, tokens and passwords are masked; the eye next to each one reveals it on request.\n    const SECRET_FIELDS = ['TELEGRAM_BOT_TOKEN', 'DISCORD_WEBHOOK_URL', 'LLM_API_KEY', 'FIRMS_MAP_KEY', 'FRED_API_KEY', 'BLS_API_KEY',\n      'OPENSKY_CLIENT_SECRET', 'EIA_API_KEY', 'FMP_API_KEY', 'FINNHUB_API_KEY', 'AISSTREAM_API_KEY', 'CLOUDFLARE_API_TOKEN'];\n    const SECRET_LABELS = {\n      hu: { show: 'Érték megjelenítése', hide: 'Érték elrejtése' },\n      en: { show: 'Show value', hide: 'Hide value' },\n      fr: { show: 'Afficher la valeur', hide: 'Masquer la valeur' },\n    };\n    const EYE_SVG = '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\">'\n      + '<path class=\"lid\" d=\"M1.5 12S5.5 5 12 5s10.5 7 10.5 7-4 7-10.5 7S1.5 12 1.5 12z\"/>'\n      + '<circle class=\"pupil\" cx=\"12\" cy=\"12\" r=\"3\"/>'\n      + '<path class=\"slash\" d=\"M3.5 3.5l17 17\"/></svg>';\n\n    function refreshSecretLabels() {\n      const l = SECRET_LABELS[currentLang] || SECRET_LABELS.hu;\n      document.querySelectorAll('.secret-eye').forEach(btn => {\n        const label = btn.getAttribute('aria-pressed') === 'true' ? l.hide : l.show;\n        btn.setAttribute('aria-label', label);\n        btn.title = label;\n      });\n    }\n\n    function initSecretFields() {\n      for (const id of SECRET_FIELDS) {\n        const input = document.getElementById(id);\n        if (!input || input.closest('.secret-wrap')) continue;\n        input.type = 'password';\n        input.setAttribute('autocomplete', 'new-password');\n        input.setAttribute('spellcheck', 'false');\n        const wrap = document.createElement('div');\n        wrap.className = 'secret-wrap';\n        input.parentNode.insertBefore(wrap, input);\n        wrap.appendChild(input);\n        const btn = document.createElement('button');\n        btn.type = 'button';\n        btn.className = 'secret-eye';\n        btn.setAttribute('aria-pressed', 'false');\n        btn.setAttribute('aria-controls', id);\n        btn.innerHTML = EYE_SVG;\n        btn.addEventListener('click', () => {\n          const show = btn.getAttribute('aria-pressed') !== 'true';\n          btn.setAttribute('aria-pressed', String(show));\n          input.type = show ? 'text' : 'password';\n          btn.classList.remove('blink');\n          void btn.offsetWidth; // restart the blink animation\n          btn.classList.add('blink');\n          refreshSecretLabels();\n        });\n        wrap.appendChild(btn);\n      }\n      refreshSecretLabels();\n    }\n\n    window.addEventListener('DOMContentLoaded', () => {\n      initSecretFields();\n      loadConfig();\n    });\n  </script>\n</body>\n</html>\n";

export function getSetupHtml() {
  const candidatePaths = [
    process.env.CRUCIX_SETUP_HTML,
    join(ROOT, 'dashboard', 'public', 'setup.html'),
    join(process.cwd(), 'dashboard', 'public', 'setup.html'),
  ].filter(Boolean);

  for (const p of candidatePaths) {
    if (existsSync(p)) {
      try {
        return readFileSync(p, 'utf8');
      } catch {}
    }
  }

  return EMBEDDED_SETUP_HTML;
}
